package com.example.hilolive;
import android.app.*;import android.os.*;import android.content.*;import android.media.projection.MediaProjectionManager;import android.provider.Settings;import android.net.Uri;import android.graphics.Color;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
 private final int REQ=100; private TextView report,history,status;private EditText higher,lower,current;private SeekBar cropX,cropY,cropW,cropH;private int last=-1;private final ArrayList<String> cards=new ArrayList<>();private long started=System.currentTimeMillis();private int changes=0;
 private final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){String card=i.getStringExtra("card"),ocr=i.getStringExtra("ocr");int r=Engine.rank(card);if(r>=0&&r!=last){last=r;cards.add(card);changes++;}status.setText("OCR: "+(ocr==null?"":ocr.replace('\n',' ')));refresh();}};
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout outer=new LinearLayout(this);outer.setOrientation(1);outer.setPadding(22,22,22,22);ScrollView scroll=new ScrollView(this);scroll.addView(outer);setContentView(scroll);
 title(outer,"HiLo Live Analyzer");label(outer,"Local-only screen OCR · no bets placed · no Stake login");Button start=button(outer,"Start screen capture",()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},9);MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);startActivityForResult(m.createScreenCaptureIntent(),REQ);});button(outer,"Stop capture",()->stopService(new Intent(this,CaptureService.class)));
 button(outer,"Enable floating overlay",()->{if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));}else Toast.makeText(this,"Overlay enabled. Start capture.",Toast.LENGTH_SHORT).show();});
 title(outer,"Screen reading area (percent)");label(outer,"Adjust until the crop contains ONLY the large current card rank. Default: central screen. Preview OCR text below.");cropX=seek(outer,"Left",30);cropY=seek(outer,"Top",25);cropW=seek(outer,"Width",40);cropH=seek(outer,"Height",30);button(outer,"Apply crop",()->{Intent i=new Intent(this,CaptureService.class);i.setAction("CROP");i.putExtra("x",cropX.getProgress());i.putExtra("y",cropY.getProgress());i.putExtra("w",cropW.getProgress());i.putExtra("h",cropH.getProgress());startService(i);});
 title(outer,"Total multipliers (from game)");label(outer,"Use TOTAL displayed multipliers, not next-step multipliers. Update as the round progresses.");higher=field(outer,"Higher/same total ×", "1.84");lower=field(outer,"Lower/same total ×","1.84");current=field(outer,"Current cashout total ×","1.00");button(outer,"Recalculate",this::refresh);
 title(outer,"Manual card override");LinearLayout line=new LinearLayout(this);line.setOrientation(LinearLayout.HORIZONTAL);outer.addView(line);Spinner spinner=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,Engine.R);spinner.setAdapter(a);line.addView(spinner,new LinearLayout.LayoutParams(0,-2,1));Button set=new Button(this);set.setText("Set card");line.addView(set);set.setOnClickListener(v->{last=spinner.getSelectedItemPosition();cards.add(Engine.R[last]);changes++;refresh();});
 title(outer,"Live analysis");report=label(outer,"Waiting for a card...");title(outer,"Card history & session");history=label(outer,"No cards yet");status=label(outer,"OCR not running");button(outer,"Clear history",()->{cards.clear();changes=0;started=System.currentTimeMillis();refresh();});button(outer,"Share session report",()->{Intent s=new Intent(Intent.ACTION_SEND);s.setType("text/plain");s.putExtra(Intent.EXTRA_TEXT,report.getText()+"\n"+history.getText());startActivity(Intent.createChooser(s,"Export analysis"));});refresh();}
 private void refresh(){if(report==null)return;double h=parse(higher),l=parse(lower),c=parse(current);report.setText(Engine.analysis(last,h,l,c));long minutes=(System.currentTimeMillis()-started)/60000;history.setText("Cards seen: "+changes+" · Session: "+minutes+" min\n"+String.join(" → ",cards.subList(Math.max(0,cards.size()-40),cards.size()))+"\nAlert: OCR is unverified; independent draws make streaks non-predictive." );}
 private double parse(EditText e){try{return Double.parseDouble(e.getText().toString());}catch(Exception ex){return 0;}}
 private TextView label(LinearLayout p,String s){TextView t=new TextView(this);t.setText(s);t.setTextSize(15);t.setTextColor(Color.DKGRAY);t.setPadding(0,6,0,12);p.addView(t);return t;}
 private void title(LinearLayout p,String s){TextView t=label(p,s);t.setTextSize(21);t.setTextColor(Color.BLACK);}
 private Button button(LinearLayout p,String text,Runnable action){Button b=new Button(this);b.setText(text);p.addView(b);b.setOnClickListener(v->action.run());return b;}
 private EditText field(LinearLayout p,String name,String def){label(p,name);EditText e=new EditText(this);e.setInputType(8194);e.setSingleLine(true);e.setText(def);p.addView(e);return e;}
 private SeekBar seek(LinearLayout p,String label,int n){TextView l=label(p,label+": "+n+"%");SeekBar s=new SeekBar(this);s.setMax(100);s.setProgress(n);p.addView(s);s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean user){l.setText(label+": "+v+"%");}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});return s;}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==REQ&&result==RESULT_OK&&data!=null){Intent i=new Intent(this,CaptureService.class);i.setAction("START");i.putExtra("result",result);i.putExtra("data",data);i.putExtra("x",cropX.getProgress());i.putExtra("y",cropY.getProgress());i.putExtra("w",cropW.getProgress());i.putExtra("h",cropH.getProgress());startForegroundService(i);}}
 @Override protected void onStart(){super.onStart();IntentFilter f=new IntentFilter("com.example.hilolive.UPDATE");if(Build.VERSION.SDK_INT>=33)registerReceiver(receiver,f,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(receiver,f);}
 @Override protected void onStop(){super.onStop();unregisterReceiver(receiver);}
}
